-- Initial schema: users, families, events, participants, invites, sessions.
--
-- Conventions:
--   * UUID primary keys generated by Postgres (gen_random_uuid, built in since PG 13).
--   * All timestamps are timestamptz (stored in UTC, converted at the edges).
--   * Tenant isolation: every family-owned row carries family_id, and composite
--     foreign keys make cross-family references impossible at the database level.

-- +goose Up

-- +goose StatementBegin
CREATE FUNCTION set_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;
-- +goose StatementEnd

-- Users are created on first OIDC login. Identity is (issuer, subject):
-- email can change at the provider and must not be used as a key.
CREATE TABLE users (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    oidc_issuer  text        NOT NULL,
    oidc_subject text        NOT NULL,
    email        text        NOT NULL,
    name         text        NOT NULL,
    avatar_url   text,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT users_oidc_identity_key UNIQUE (oidc_issuer, oidc_subject)
);

CREATE TRIGGER users_set_updated_at
    BEFORE UPDATE ON users
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

CREATE TABLE families (
    id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name       text        NOT NULL CHECK (char_length(name) BETWEEN 1 AND 100),
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE family_members (
    family_id uuid        NOT NULL REFERENCES families (id) ON DELETE CASCADE,
    user_id   uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role      text        NOT NULL DEFAULT 'member' CHECK (role IN ('owner', 'member')),
    joined_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (family_id, user_id)
);

-- MVP: a user belongs to at most one family. Drop this index to allow several.
CREATE UNIQUE INDEX family_members_one_family_per_user ON family_members (user_id);

CREATE TABLE events (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    family_id   uuid        NOT NULL REFERENCES families (id) ON DELETE CASCADE,
    title       text        NOT NULL CHECK (char_length(title) BETWEEN 1 AND 200),
    description text        NOT NULL DEFAULT '' CHECK (char_length(description) <= 5000),
    starts_at   timestamptz NOT NULL,
    ends_at     timestamptz NOT NULL,
    all_day     boolean     NOT NULL DEFAULT false,
    -- Kept nullable so events survive when their author leaves.
    created_by  uuid        REFERENCES users (id) ON DELETE SET NULL,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT events_time_range_check CHECK (ends_at >= starts_at),
    -- Target for the composite FK from event_participants.
    CONSTRAINT events_id_family_key UNIQUE (id, family_id)
);

-- Calendar view: events of one family in a time window.
CREATE INDEX events_family_starts_at_idx ON events (family_id, starts_at);

CREATE TRIGGER events_set_updated_at
    BEFORE UPDATE ON events
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- A participant must be a member of the same family as the event:
-- both foreign keys share family_id, so this is enforced by Postgres.
-- Removing a member from the family removes them from its events.
CREATE TABLE event_participants (
    event_id  uuid        NOT NULL,
    family_id uuid        NOT NULL,
    user_id   uuid        NOT NULL,
    added_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (event_id, user_id),
    FOREIGN KEY (event_id, family_id) REFERENCES events (id, family_id) ON DELETE CASCADE,
    FOREIGN KEY (family_id, user_id) REFERENCES family_members (family_id, user_id) ON DELETE CASCADE
);

-- "My events" and FK checks on member removal.
CREATE INDEX event_participants_family_user_idx ON event_participants (family_id, user_id);

-- Invite links. Only a SHA-256 hash of the token is stored, so a database
-- leak does not expose usable invites.
CREATE TABLE family_invites (
    id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    family_id  uuid        NOT NULL REFERENCES families (id) ON DELETE CASCADE,
    token_hash bytea       NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),
    created_by uuid        REFERENCES users (id) ON DELETE SET NULL,
    expires_at timestamptz NOT NULL,
    used_at    timestamptz,
    used_by    uuid        REFERENCES users (id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX family_invites_family_id_idx ON family_invites (family_id);

-- Server-side sessions (BFF). The cookie holds a random token; only its
-- SHA-256 hash is stored, so a database leak does not expose live sessions.
CREATE TABLE sessions (
    token_hash   bytea PRIMARY KEY CHECK (octet_length(token_hash) = 32),
    user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    created_at   timestamptz NOT NULL DEFAULT now(),
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    expires_at   timestamptz NOT NULL
);

CREATE INDEX sessions_user_id_idx ON sessions (user_id);
-- Periodic cleanup of expired sessions.
CREATE INDEX sessions_expires_at_idx ON sessions (expires_at);

-- +goose Down
DROP TABLE sessions;
DROP TABLE family_invites;
DROP TABLE event_participants;
DROP TABLE events;
DROP TABLE family_members;
DROP TABLE families;
DROP TABLE users;
DROP FUNCTION set_updated_at();
